@startuml ClassDiagram
class Game {
  - id: string
  - score: int
  + play(): void
  + viewScore(): int
}
class Question {
  - id: string
  - prompt: string
  - options: List<string>
  + getPrompt(): string
  + getOptions(): List<string>
}
class User {
  - id: string
  - username: string
  + playGame(game: Game): void
  + viewScore(game: Game): int
}
class Admin {
  - id: string
  - username: string
  + updateQuestions(questions: List<Question>): void
}
Game --* Question
User --* Game
Admin --* Question
@enduml

@startuml ActivityDiagram
start
:play game;
if (game over?) then (yes)
  :game over;
else (no)
  :continue playing;
endif
:calculate score;
:display score;
stop
@enduml

@startuml SequenceDiagram2
participant Admin
participant Question
Admin->>Question: update()
Question->>Admin: return success
@enduml

@startuml PackageDiagram
package Game {
  class Game
  class Question
}
package User {
  class User
}
package Admin {
  class Admin
}
Game -- User
Game -- Admin
@enduml

